//! ECDEV side of the Trend-Finder clustering benchmark: the unmodified
//! ecdev_core::social::clusters over the same posts and the same groups as the donor run.
//! usage: ecdev-side <out/posts.jsonl> <out/donor.json> <out/ecdev.json>
use ecdev_core::social::{EvidenceState, SocialEngagement, SocialPost, clusters};
use serde_json::{Value, json};
use std::collections::BTreeMap;
use std::time::Instant;

fn main() {
    let a: Vec<String> = std::env::args().collect();
    let posts: BTreeMap<String, Value> = std::fs::read_to_string(&a[1])
        .unwrap()
        .lines()
        .map(|l| {
            let v: Value = serde_json::from_str(l).unwrap();
            (v["id"].as_str().unwrap().to_string(), v)
        })
        .collect();
    let donor: Value = serde_json::from_str(&std::fs::read_to_string(&a[2]).unwrap()).unwrap();
    let mut out = json!({});
    for (setting, runs) in donor["setting"].as_object().unwrap() {
        let mut results = vec![];
        for run in runs.as_array().unwrap() {
            let social: Vec<SocialPost> = run["posts"]
                .as_array()
                .unwrap()
                .iter()
                .map(|id| {
                    let p = &posts[id.as_str().unwrap()];
                    SocialPost {
                        platform: "REDDIT".into(),
                        provider: "benchmark".into(),
                        source_url: String::new(),
                        native_id: p["id"].as_str().unwrap().into(),
                        thread_id: None,
                        author_id: None,
                        publisher: None,
                        published_at: p["published_at"].as_u64(),
                        captured_at: 0,
                        text: p["text"].as_str().unwrap().into(),
                        language: Some("en".into()),
                        media: vec![],
                        hashtags: vec![],
                        mentions: vec![],
                        entities: vec![],
                        propagation: "ORIGINAL".into(),
                        parent_id: None,
                        engagement: SocialEngagement { views: None, likes: None, comments: None, reposts: None, favorites: None, followers: None },
                        raw_hash: String::new(),
                        raw_locator: String::new(),
                        extraction_method: "benchmark".into(),
                        state: EvidenceState::Observed,
                        capture_mode: "FIXTURE".into(),
                        evidence_id: p["id"].as_str().unwrap().into(),
                        freshness_seconds: None,
                        origin_evidence_id: None,
                    }
                })
                .collect();
            let t = Instant::now();
            let cs = clusters(&social);
            let seconds = t.elapsed().as_secs_f64();
            let mut label: BTreeMap<String, i64> = BTreeMap::new();
            for (i, c) in cs.iter().enumerate() {
                for k in c["observations"].as_array().unwrap() {
                    let id = k.as_str().unwrap().trim_start_matches("REDDIT:").to_string();
                    label.insert(id, i as i64);
                }
            }
            let labels: Vec<i64> = run["posts"].as_array().unwrap().iter().map(|id| label[id.as_str().unwrap()]).collect();
            let terms: Vec<Value> = cs.iter().map(|c| c["terms"].clone()).collect();
            results.push(json!({"niche":run["niche"],"week":run["week"],"posts":run["posts"],"labels":labels,"terms":terms,"seconds":seconds}));
        }
        out[setting] = json!(results);
    }
    std::fs::write(&a[3], serde_json::to_string(&out).unwrap()).unwrap();
}
